fn main() {
    let mut s = String::new();
    let data = "initial contents";
    let s1 = data.to_string();               // &str -> String
    let s2 = String::from("initial contents"); // the same
    s.push_str("foo");                       // append a &str
    s.push('!');                             // append one char
    let hello = String::from("Dobrý den");   // any UTF-8 text
    println!("{s} | {s1} | {s2} | {hello}");
}

fn main() {
    let s1 = String::from("Hello, ");
    let s2 = String::from("world!");
    let s3 = s1 + &s2; // s1 is moved here; s2 is only borrowed
    println!("{s3} ({s2} still usable)");

    let a = String::from("tic");
    let b = String::from("tac");
    let c = String::from("toe");
    let game = format!("{a}-{b}-{c}");
    println!("{game}; {a} {b} {c} are all still usable");
}

fn main() {
    let hello = "Здравствуйте";
    println!("{} chars, {} bytes", hello.chars().count(), hello.len());
    println!("first two bytes: {:?}", &hello.as_bytes()[..2]);
    println!("first char: {:?}", hello.chars().next());
}

fn main() {
